import React, { useState, useEffect } from 'react';
import { Trash2, Plus, X, MessageSquare, Users, Settings, BarChart3, Eye, Download, Filter, LogOut, Lock, Menu } from 'lucide-react';

const API_URL = 'https://camt-production.up.railway.app';

export default function UnifiedAdminPanel() {
  const [token, setToken] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [activeTab, setActiveTab] = useState('channels');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [initializing, setInitializing] = useState(true); // New state for initial load
  
  // Channel management
  const [channels, setChannels] = useState([]);
  const [showAddChannel, setShowAddChannel] = useState(false);
  const [newChannel, setNewChannel] = useState({
    name: '',
    category: 'Support',
    description: '',
    isPublic: true
  });
  
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [messages, setMessages] = useState([]);
  
  // Assessment results
  const [stats, setStats] = useState(null);
  const [assessmentResults, setAssessmentResults] = useState([]);
  const [filteredResults, setFilteredResults] = useState([]);
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({
    ageMin: '',
    ageMax: '',
    scoreMin: '',
    scoreMax: '',
    sortBy: 'score-desc',
    school: ''
  });
  
  const [confirmDialog, setConfirmDialog] = useState({
    show: false,
    title: '',
    message: '',
    onConfirm: null
  });

  const handleLogin = async () => {
    if (!password) {
      setError('Şifre gereklidir');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_URL}/api/auth/admin-login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password })
      });
      
      const data = await response.json();
      
      console.log('Login response:', { ok: response.ok, status: response.status, hasToken: !!data.token });
      
      if (response.ok && data.token) {
        setToken(data.token);
        setIsAuthenticated(true);
        localStorage.setItem('adminToken', data.token);
        setPassword('');
        
        // Wait a bit for token to propagate
        await new Promise(resolve => setTimeout(resolve, 100));
        
        // Try to load data with the new token (these are optional, don't fail login)
        await loadChannels(data.token);
        await loadStats(data.token);
      } else {
        setError(data.error || 'Giriş başarısız');
      }
    } catch (error) {
      console.error('Login error:', error);
      setError('Bağlantı hatası. Lütfen tekrar deneyin.');
